import pandas as pd
import json
import base64
import os

# 1. Load Data
df = pd.read_csv('/app/benchmark/data.csv')

# Parse dates
df['order_date'] = pd.to_datetime(df['order_date'])
df['year_month'] = df['order_date'].dt.to_period('M').astype(str)

# 2. Calculate KPIs
total_revenue = df['revenue'].sum()
total_profit = df['profit'].sum()
avg_profit_margin = (total_profit / total_revenue * 100) if total_revenue else 0
avg_order_value = df['revenue'].mean()
discount_utilization = (df['discount'] > 0).mean() * 100

# 3. Aggregations for Charts
# Sales Trends (Monthly)
monthly_sales = df.groupby('year_month').agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum'),
    orders=('order_id', 'count')
).reset_index()

# Discount Impact
# Add profit margin per transaction
df['margin'] = (df['profit'] / df['revenue'].replace(0, 0.01)) * 100
discount_impact = df.groupby('discount').agg(
    avg_margin=('margin', 'mean'),
    revenue=('revenue', 'sum'),
    orders=('order_id', 'count')
).reset_index()

# Top Products
top_products = df.groupby('product_id').agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum')
).sort_values(by='revenue', ascending=False).head(10).reset_index()

# Top Stores
top_stores = df.groupby('store_id').agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum')
).sort_values(by='revenue', ascending=False).head(10).reset_index()

# Customer Behavior (RFM proxy)
customer_stats = df.groupby('customer_id').agg(
    orders=('order_id', 'count'),
    revenue=('revenue', 'sum')
)
repeat_customers = (customer_stats['orders'] > 1).sum()
total_customers = len(customer_stats)
repeat_customer_rate = (repeat_customers / total_customers * 100) if total_customers else 0

# Convert data to JSON for Chart.js
chart_data = {
    'monthly_sales': {
        'labels': monthly_sales['year_month'].tolist(),
        'revenue': monthly_sales['revenue'].tolist(),
        'profit': monthly_sales['profit'].tolist(),
        'orders': monthly_sales['orders'].tolist(),
    },
    'discount_impact': {
        'labels': discount_impact['discount'].astype(str).tolist(),
        'avg_margin': discount_impact['avg_margin'].tolist(),
        'orders': discount_impact['orders'].tolist()
    },
    'top_products': {
        'labels': top_products['product_id'].tolist(),
        'revenue': top_products['revenue'].tolist()
    },
    'top_stores': {
        'labels': top_stores['store_id'].tolist(),
        'revenue': top_stores['revenue'].tolist()
    }
}

# 4. Generate HTML Report
html_template = f"""<!DOCTYPE html>
<html lang="en">
<head>
