            options: {{
                responsive: true,
                maintainAspectRatio: false,
                indexAxis: 'y'
            }}
        }});

        // Store Performance Chart
        new Chart(document.getElementById('storeChart'), {{
            type: 'bar',
            data: {{
                labels: chartData.top_stores.labels,
                datasets: [{{
                    label: 'Revenue ($)',
                    data: chartData.top_stores.revenue,
                    backgroundColor: '#e67e22'
                }}]
            }},
            options: {{
                responsive: true,
                maintainAspectRatio: false,
                indexAxis: 'y'
            }}
        }});

        // Discount Impact Chart
        new Chart(document.getElementById('discountChart'), {{
            type: 'bar',
            data: {{
                labels: chartData.discount_impact.labels,
                datasets: [
                    {{
                        label: 'Order Volume',
                        data: chartData.discount_impact.orders,
                        backgroundColor: '#95a5a6',
                        yAxisID: 'y'
