                        borderColor: '#e74c3c',
                        backgroundColor: '#e74c3c',
                        yAxisID: 'y1'
                    }}
                ]
            }},
            options: {{
                responsive: true,
                maintainAspectRatio: false,
                scales: {{
                    y: {{
                        type: 'linear',
                        display: true,
                        position: 'left',
                        title: {{ display: true, text: 'Order Volume' }}
                    }},
                    y1: {{
                        type: 'linear',
                        display: true,
                        position: 'right',
                        title: {{ display: true, text: 'Avg Profit Margin (%)' }},
                        grid: {{ drawOnChartArea: false }}
                    }}
                }}
            }}
        }});
